def check_r5(root):
    stylesheet_links = [n for n in nodes(root) if n.tag == 'link'
                        and 'stylesheet' in n.attrs.get('rel', '').lower().split()
                        and re.fullmatch(r'(?:\.\./|\./)?assets/site\.css(?:[?#].*)?', n.attrs.get('href', ''))]
    forbidden = re.compile(r'(?<![-\w])(?:width|min-width|max-width|display|position|float|overflow(?:-[xy])?|grid(?:-[\w-]+)?|flex(?:-[\w-]+)?|font(?:-[\w-]+)?|color|background(?:-[\w-]+)?)\s*:', re.I)
    relevant = re.compile(r'(?:^|[\s>+~,])(?:html|body)(?:\b|[.#:[ ])|\.(?:container|day|foundation-refresh|topic-card|technical[\w-]*)(?![\w-])|#part-2\b', re.I)
    items = []
    block_overrides = 0
    attribute_overrides = 0
    for node in nodes(root):
        if node.tag == 'style':
            css = re.sub(r'/\*.*?\*/', '', node.text(), flags=re.S)
            for match in re.finditer(r'([^{}]+)\{([^{}]*)\}', css):
                selector, declarations = match.groups()
                if relevant.search(selector) and forbidden.search(declarations):
                    block_overrides += 1
                    items.append('inline <style> overrides container/layout/font/palette: ' + selector.strip())
        if node.attrs.get('style') and forbidden.search(node.attrs['style']):
            identifier = node.attrs.get('id', '')
            classes = node.cls()
            affects_container = node.tag in ('html', 'body') or identifier == 'part-2' or identifier.endswith('-technical') or bool(classes & {'container', 'day', 'foundation-refresh', 'topic-card', 'technical', 'technical-discussion'})
            if affects_container:
                attribute_overrides += 1
                items.append('inline style attribute overrides container: ' + node.tag + '#' + identifier)
    if not stylesheet_links:
        items.insert(0, 'missing local assets/site.css stylesheet link')
    failures = (not stylesheet_links) + block_overrides + attribute_overrides
    return result('R5 shared stylesheet', 'FAIL' if failures else 'PASS', True,
                  f'{len(stylesheet_links)} shared stylesheet link(s); {block_overrides} inline block override(s); {attribute_overrides} inline attribute override(s)', items)
